using System;
namespace PZ3D { static class PortableDeploymentTests {static void Check(bool value,string label){Console.WriteLine((value?"PASS: ":"FAIL: ")+label);if(!value)throw new Exception(label);}public static void Run(){Check(typeof(Engine).Assembly.GetType("PZ3D.PortableDeployment")!=null,"registry-free deployment supports scoped uninstall");
string root=System.IO.Path.Combine(@"E:\AppCaches\Temp","orange-install-test-"+Guid.NewGuid().ToString("N"));var files=new System.Collections.Generic.Dictionary<string,byte[]>{{"橙子启动器.exe",new byte[]{1,2,3}},{"卸载橙子启动器.exe",new byte[]{4,5,6}}};PortableDeployment.Install(root,files);Check(System.IO.File.Exists(System.IO.Path.Combine(root,"orange-installation.json")),"installation creates owned manifest without registering external application state");
System.IO.File.WriteAllText(System.IO.Path.Combine(root,"personal.txt"),"keep");System.IO.File.WriteAllText(System.IO.Path.Combine(root,"OrangeLauncherRuntime","cache.tmp"),"ownedcache");PortableDeployment.Uninstall(root);Check(System.IO.File.Exists(System.IO.Path.Combine(root,"personal.txt"))&&!System.IO.File.Exists(System.IO.Path.Combine(root,"橙子启动器.exe"))&&!System.IO.Directory.Exists(System.IO.Path.Combine(root,"OrangeLauncherRuntime")),"uninstall removes owned application/cache and preserves unrelated file");
string edited=root+"-edited";PortableDeployment.Install(edited,files);System.IO.File.WriteAllText(System.IO.Path.Combine(edited,"橙子启动器.exe"),"userchanged");PortableDeployment.Uninstall(edited);Check(System.IO.File.Exists(System.IO.Path.Combine(edited,"橙子启动器.exe"))&&System.IO.File.Exists(System.IO.Path.Combine(edited,"orange-installation.json")),"uninstall retains modified application and recovery ownership record");
string locked=root+"-locked";PortableDeployment.Install(locked,files);using(var handle=new System.IO.FileStream(System.IO.Path.Combine(locked,"橙子启动器.exe"),System.IO.FileMode.Open,System.IO.FileAccess.ReadWrite,System.IO.FileShare.None)){bool refused=false;try{PortableDeployment.Uninstall(locked);}catch{refused=true;}Check(refused&&System.IO.File.Exists(System.IO.Path.Combine(locked,"卸载橙子启动器.exe")),"occupied application refuses uninstall before deleting any owned files");}
bool denied=false;try{PortableDeployment.Install(@"E:\",files);}catch{denied=true;}Check(denied,"drive root cannot be an installation deletion target");denied=false;try{PortableDeployment.Install(root,files);}catch{denied=true;}Check(denied&&System.IO.File.ReadAllText(System.IO.Path.Combine(root,"personal.txt"))=="keep","nonempty foreign target refused without overwrite");
}public static int Main(){try{Run();return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}} }
